import io
p = "experiments/E358_wiring-head-on-attached-ends/experiment.md"
s = io.open(p, encoding="utf-8", newline="").read()
nl = "\r\n" if "\r\n" in s else "\n"
def rep(a, b):
    global s
    assert s.count(a) == 1, (a[:80], s.count(a))
    s = s.replace(a, b)
rep("or the TRAIN share of ends whose nearest candidate piece end lies within 0.5 m differing from the VAL share by more than 0.10 (absolute)", "or the share of LABELLED ends whose nearest candidate piece end lies within 0.5 m, measured on the UNPERTURBED TRAIN records, differing from the VAL share by more than 0.10 (absolute; the share of the jittered training draw is logged and shown next to it as a note, because the jitter lowers it a lot)")
rep("the no-jitter ablation head `wn`: same records, jitter scale 0, a few seconds on the cached features, tag e358wn, reported)", "the no-jitter ablation head `wn`: same records and head seed 0 but NO perturbation at all (neither the position jitter nor the 4 degree heading rotation), a few minutes on the cached features, tag e358wn, reported)")
rep("## 3. Risks", "**Live-check rule (written now, before any number; the live pass loads `map_mode=\"exact\"`, the stored dump was made with `\"error\"`, `jwire_data.py:158` against `jends_eval.py:42`):** run order: the stored attached-end cache (`jwire_data.py val ... --ends att`, made by the cheap gate) first, then `jwire_check.py live --ends att --device cpu` on 24 `val_clean` frames. **ACCEPTED** (every field equal except at most one pair near p = 0.1 in one frame, atol 2e-3) is a precondition for the GPU runs `E358.w_s*`. **REFUSED** means NO GPU job, no widening of the tolerance after the diff has been seen, and the lead decides between a fix of the loader and a documented shift (then the card says so and the jobs start only after that).\r\n\r\n## 3. Risks".replace("\r\n", nl))
rep("## 5. Build log" + nl + "(empty)", "## 5. Build log" + nl + "**Build (ar-coder, CPU only, 2026-11-16 09:10 - 10:35):** `evaluation/jwire_data.py` (end kind `ends` end to end: `check_ends`, `frame_dict`, caches / metas / names only for att), `training/train/jwire_train.py` (`--ends`, the no-jitter head `wn`), `evaluation/jwire_verdict.py` (`--read-out primary`, INVALID cases, near05 shift note), `evaluation/jwire_check.py` (`--read-out`, `--ends`), READMEs, the staged scorer copies in `temp/_session_scratch_e358/stage/` with `staged_diff.patch` here (6 hunks), tests (four selftests, 7 staged tests) and mutation evidence 98 of 98 killed; kp records bit for bit unchanged on 40 VAL frames for `e312_p_s0` and `e324_s_s0`; arm t (twin on the attached ends) reproduces the stored PRIMARY card of both seeds exactly (numbers, curves, wired, per-frame counts). Deviations of the coder (kept, none changes a number): the meta carries `ends` only for att (kp unchanged), `wn` = no perturbation at all and is trained on every run, `near05` counts labelled ends, `--ends att` is refused on E312's default pair run. **Code critic (fresh ar-critic, mode code) 10:30: no blocking defect; READY for the CPU gate, READY for the GPU run once the gate passed and the live check is ACCEPTED.** Should-fix items taken (follow-up of the coder, 10:40): the jittered draw's near05 is logged and shown as a note; the staged scorer refuses `--wire` with `--attach` and without `--snap-nogeom`; the live-check rule is written above; the `wn` and near05 definitions are stated in the card; also the verdict reads the `wn` card and prints the prediction hit window; the rebound local `ends` in `record_of` is renamed.")
rep("A code critic on the build (section 2 step 5) is required before any GPU job.", "A code critic on the build (section 2 step 5) is required before any GPU job: **done 2026-11-16 10:30, no blocking defect (section 5).**")
io.open(p, "w", encoding="utf-8", newline="").write(s)
print("ok")
